#!/bin/sh
# Usage: check_markdown.sh <built-site-dir>
#
# Verifies the Markdown pages generated by make_markdown.sh. Fails on:
#   - an HTML page without a non-empty .md page
#   - a code block of the HTML page (pre/code) missing or altered in the .md
#   - an llms.txt link that is not an absolute URL of a generated .md page,
#     or a generated .md page that llms.txt does not link
#   - site chrome (navigation, footer, pager, scripts, raw HTML, inline
#     diagrams) or internal .html links left in a .md page
set -eu

dir=${1:?usage: check_markdown.sh <built-site-dir>}
base=https://zorba-processor.github.io/zorba/
fail=0
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

problem() {
  echo "FAIL: $*"
  fail=1
}

# Text of every code block, whitespace-normalized, one block per line.
code_blocks() { # <format> <file>
  pandoc --from="$1" --to=json "$2" | jq -r '
    [.. | objects | select(.t == "CodeBlock") | .c[1]
     | gsub("\\s+"; " ") | sub("^ "; "") | sub(" $"; "")] | .[]'
}

for html in "$dir"/*.html; do
  page=$(basename "$html" .html)
  md=$dir/$page.md

  if [ ! -s "$md" ]; then
    problem "$page.md is missing or empty"
    continue
  fi

  code_blocks html "$html" > "$tmp/html.txt"
  code_blocks gfm "$md" > "$tmp/md.txt"
  if ! cmp -s "$tmp/html.txt" "$tmp/md.txt"; then
    problem "$page.md: code blocks differ from $page.html"
    diff "$tmp/html.txt" "$tmp/md.txt" | head -10 || true
  fi

  # Outside fenced code blocks only: code may contain any text.
  awk '/^```/ { fence = !fence; next } !fence' "$md" > "$tmp/prose.txt"
  if grep -nE 'On this page|Source on GitHub|Every example on this site is run|aria-current|site\.js|^\[Next: |<(header|footer|nav|script|svg|div|details|figure)|data:image' "$tmp/prose.txt" > "$tmp/chrome.txt"; then
    problem "$page.md: leftover site chrome"
    head -5 "$tmp/chrome.txt"
  fi

  if grep -nE '\]\((\./)?[A-Za-z0-9_-]+\.html(#[^)]*)?\)' "$tmp/prose.txt" > "$tmp/links.txt"; then
    problem "$page.md: internal link to .html"
    head -5 "$tmp/links.txt"
  fi

  echo "ok: $page.md ($(wc -c < "$md" | tr -d ' ') bytes, $(wc -l < "$tmp/md.txt" | tr -d ' ') code blocks)"
done

llms=$dir/llms.txt
if [ ! -s "$llms" ]; then
  problem "llms.txt is missing or empty"
else
  grep -o '](https\{0,1\}://[^)]*)' "$llms" | sed 's/^](//; s/)$//' > "$tmp/urls.txt"
  for url in $(grep "^$base" "$tmp/urls.txt"); do
    file=${url#"$base"}
    case "$file" in
      *.md) [ -s "$dir/$file" ] || problem "llms.txt links $url, which is not a generated page" ;;
      *) problem "llms.txt links $url, which is not a .md page" ;;
    esac
  done
  for md in "$dir"/*.md; do
    grep -qx "$base$(basename "$md")" "$tmp/urls.txt" ||
      problem "llms.txt does not link $(basename "$md")"
  done
  echo "ok: llms.txt ($(grep -c "^$base" "$tmp/urls.txt") page links)"
fi

exit "$fail"
